~()?\"']/g, ' ')\n .replace(/\\s+/g,:
~()?"']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Motor de căutare și interogare semantică de înaltă precizie
 */
exportați funcția asincronă searchSentences(
  interogare:șir,
  filtre: SearchFilterOptions = {}
): Promise<{ rezultate: SentenceItem[]; total:numar; semanticMatches?: SemanticExplanationMatch[] }> {
  const all = await loadSentences();
  const normalizedQuery = normalizeText(interogare);
  const queryTokens = normalizedQuery ? normalizedQuery.split(' ').filter(Boolean) : [];

  const {
    cefr = 'toate',
    secțiune = „toate”,
    categorie = „toate”,
    subcategorie = „toate”,
    gramatica = „toate”,
    formalitate = „toate”,
    limita = 50,
    offset = 0,
  } = filtre;

  // Filtru trece
  let filtered = all.filter(s => {
    if (cefr !== 'toate' && s.cefr !== cefr) returnează false;
    if (sectiunea !== 'toate' && s.section !==sectiunea) returneaza false;
    if (categoria !== 'toate' && s.category !== categorie) returnează false;
    if (subcategoria !== 'toate' && s.subcategoria !== subcategorie) returnează false;
    if (gramatica !== 'toate' && !s.grammar.toLowerCase().includes(gramatica.toLowerCase())) returneaza false;
    if (formality !== 'toate' && s.formality.toLowerCase() !== formality.toLowerCase()) returnează false;
    returnează adevărat;
  });

  dacă (!normalizedQuery) {
    const total = filtrat.lungime;
    const paginated = filtrat. slice(offset, offset + limit);
    return { rezultate: paginat, total };
  }

  // Algoritm de scor
  interfaceScoredItem {
    item:SentenceItem;
    scor:numar;
    aspect: SemanticExplanationMatch['matchedAspect'];
  }

  const scor: ScoredItem[] = [];

  for (const s of filtrat) {
    fie scor = 0;
    let matchedAspect: SemanticExplanationMatch['matchedAspect'] = 'engleză';

    const normEn = normalizeText(s.english);
    const normEg = normalizeText(s.arabicEg);
    const normFusha = normalizeText(s.arabicFusha);
    const normGrammar = normalizeText(s.gramatica);
    const normPurpose = normalizeText(s.scop);

    // Potrivirea exactă a propoziției complete
    if (normEn === normalizedQuery) {
      scor += 100;
      matchedAspect = 'engleză';
    } else if (normEg === normalizedQuery) {
      scor += 95;
      matchedAspect = 'arabic-eg';
    } else if (normFusha === normalizedQuery) {
      scor += 90;
      matchedAspect = 'arabic-fusha';
    }

    //Subșirul conține
    if (normEn.includes(normalizedQuery)) {
      scor += 50;
      matchedAspect = 'engleză';
    } else if (normEg.includes(normalizedQuery)) {
      scor += 45;
      matchedAspect = 'arabic-eg';
    } else if (normFusha.includes(normalizedQuery)) {
      scor += 40;
      matchedAspect = 'arabic-fusha';
    } else if (normGrammar.includes(normalizedQuery)) {
      scor += 35;
      matchedAspect = 'gramatica';
    } else if (normPurpose.includes(normalizedQuery)) {
      scor += 30;
      matchedAspect = 'concept';
    }

    // Token match
    lasă tokenMatches = 0;
    pentru (const token of queryTokens) {
      if (normEn.includes(token)) tokenMatches += 5;
      if (normEg.includes(token)) tokenMatches += 4;
      if (normFusha.includes(token)) tokenMatches += 3;
      if (s.vocabulary.some(v => normalizeText(v).includes(token))) tokenMatches += 4;
      if (s.tags.some(t => normalizeText(t).includes(token))) tokenMatches += 3;
    }
    scor += tokenMatches;

    dacă (scor > 0) {
      scored.push({ item: s, scor, aspect: matchedAspect });
    }
  }

  scored.sort((a, b) => b.score - a.score);

  // Explicația semantică se potrivește pentru elementele de top
  const semanticMatches: SemanticExplanationMatch[] = scored.slice(0, 5).map(s => {
    let nuance = '';
    if (s.item.grammar.toLowerCase().includes('past continuous')) {
      nuanță = „Timpul trecut continuu arată că un eveniment a avut loc într-un anumit moment în timp din trecut.”;
    } else if (s.item.grammar.toLowerCase().includes('prezent perfect continuous')) {
      nuanță = 'Timpul prezent perfect continuu accentuează timpul din trecut și continuă până în momentul vorbirii.';
    } else if (s.item.grammar.toLowerCase().includes('futur perfect')) {
      nuanță = „Timpul viitor perfect exprimă faptul că un eveniment va fi finalizat înainte de un anumit moment în viitor.”;
    } else if (s.item.grammar.toLowerCase().includes('indirect')) {
      nuanță = 'Forma cererii indirecte este culmea etichetei diplomatice în comunicarea în limba engleză.';
    }
    întoarce {
      propoziție: articol,
      similarityScore: Math.min(100, s.score),
      nuanceExplanationAr: nuanță,
      matchedAspect: aspect,
    };
  });

  const total = punctat. lungimea;
  const paginated = scored.slice(offset, offset + limit).map(s => s.item);

  întoarce {
    rezultate: paginat,
    total,
    potriviri semantice,
  };
}

/**
 * Propoziție zilnică deterministă (identică pentru toți utilizatorii în orice zi)
 */
exportă funcția asincronă getDailySentence(): Promise<SentenceItem | nul> {
  const all = await loadSentences();
  if (all. length === 0) return null;

  const today = new Date();
  const dayOfYear = Math.floor(
    (today.getTime() - data noua(today.getFullYear(), 0, 0).getTime()) / 1000 / 60 / 60 / 24
  );
  const index = Math.abs((dayOfYear * 97 + today.getFullYear()) % all.length);
  returnează toate[indexul] || toate[0];
}

/**
 * Propoziţia deterministă a săptămânii
 */
funcția asincronă de export getSentenceOfTheWeek(): Promise<SentenceItem | nul> {
  const all = await loadSentences();
  if (all. length === 0) return null;

  const today = new Date();
  const weekNumber = Math.ceil(
    ((azi.getTime() - dată nouă(azi.getFullYear(), 0, 1). getTime()) / 86400000 + 1) / 7
  );
  // Prefer B2 sau C1 pentru propoziția săptămânii
  const b2c1 = all.filter(s => s.cefr === 'B2' || s.cefr === 'C1');
  const pool = b2c1.lungime > 0 ? b2c1:toate;
  const index = Math.abs((weekNumber * 31) % pool.length);
  pool de returnare[index] || bazin[0];
}

/**
 * Obțineți propoziție aleatorie, filtru opțional CEFR sau secțiune
 */
exportă funcția asincronă getRandomSentence(cefr?: CEFRLevel, section?: șir): Promise<SentenceItem | nul> {
  const all = await loadSentences();
  let pool = all;
  dacă (cefr) {
    pool = pool.filter(s => s.cefr === cefr);
  }
  dacă (secțiunea) {
    bazin = bazin. filtru (s => s. secțiune === secțiune);
  }
  if (pool. lungime === 0) returnează null;
  const randIdx = Math.floor(Math.random() * pool.length);
  pool de returnare[randIdx];
}
